    @EventHandler( payloadType=CreatePaymentEvent.class )
    public void handle( CreatePaymentEvent event) {
	    LOGGER.info("handling CreatePaymentEvent - " + event );
	    Payment entity = new Payment();
            entity.setPaymentId( event.getPaymentId() );
            entity.setPaymentNumber( event.getPaymentNumber() );
            entity.setAmount( event.getAmount() );
            entity.setTransactionId( event.getTransactionId() );
            entity.setAuthorizedAt( event.getAuthorizedAt() );
            entity.setCapturedAt( event.getCapturedAt() );
            entity.setStatus( event.getStatus() );
            entity.setPaymentMethod( event.getPaymentMethod() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllPayment( entity );
    }

