    /**
     * Method to retrieve the Payment via an PaymentPrimaryKey.
     * @param 	id Long
     * @return 	Payment
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Payment handle( FindPaymentQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getPaymentId() );
    }
    
    /**
     * Method to retrieve a collection of all Payments
     *
     * @param	query	FindAllPaymentQuery 
     * @return 	List<Payment> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Payment> handle( FindAllPaymentQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindPayment,
 * but only if the id matches
 *
 * @param		entity	Payment
 */
	protected void emitFindPayment( Payment entity ) {
		LOGGER.info("handling emitFindPayment" );
		
	    queryUpdateEmitter.emit(FindPaymentQuery.class,
	                            query -> query.getFilter().getPaymentId().equals(entity.getPaymentId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPayment
	 * 
	 * @param		entity	Payment
	 */
	protected void emitFindAllPayment( Payment entity ) {
		LOGGER.info("handling emitFindAllPayment" );
		
	    queryUpdateEmitter.emit(FindAllPaymentQuery.class,
	                            query -> true,
	                            entity);
	}

